def test_stops_when_encountering_non_dict():
    """If an intermediate value is not a dict, default must be returned."""
    data = {"a": {"b": 5}}          # `b` is an int, not a dict
    assert deep_get(data, "a.b.c", default="fallback") == "fallback"


